+import calculateRetryDelay from './core/calculate-retry-delay.js';
+import type {RetryObject} from './core/options.js';
+
+/**
+Preview the retry delay Got would compute for each retry context, without performing any request.
+
+Every context must set `retryOptions.noise` to `0` so the result is deterministic.
+
+@param contexts - Retry contexts in the same shape `retry.calculateDelay` receives.
+@returns The delay in milliseconds for each context, in the same order. `0` means the request would not be retried.
+@throws {RangeError} If any context has a `retryOptions.noise` other than `0`.
+
+@example
+```
+import {Options, RequestError, retrySchedule} from 'got';
+
+const options = new Options({retry: {noise: 0}});
+const error = new RequestError('Timed out', {code: 'ETIMEDOUT'}, options);
+
+retrySchedule([1, 2, 3].map(attemptCount => ({
+	attemptCount,
+	retryOptions: options.retry,
+	error,
+	computedValue: Number.POSITIVE_INFINITY,
+})));
+//=> [1000, 2000, 0]
+```
+*/
+// groundwork: allow-duplicate synchronous side-effect-free preview reusing calculateRetryDelay, unlike the async request retry path
+export default function retrySchedule(contexts: readonly RetryObject[]): number[] {
+	for (const [index, {retryOptions}] of contexts.entries()) {
+		if (retryOptions.noise !== 0) {
+			throw new RangeError(`Expected \`retryOptions.noise\` to be 0 for a deterministic retry schedule, got ${String(retryOptions.noise)} at index ${index}`);
+		}
+	}
+
+	return contexts.map(context => calculateRetryDelay(context));
+}
