@@ -0,0 +1,99 @@
+import test from 'ava';
+import {
+	Options,
+	RequestError,
+	RetryError,
+	retrySchedule,
+	type Method,
+	type RetryObject,
+	type RetryOptions,
+} from '../source/index.js';
+
+type ContextOptions = {
+	attemptCount?: number;
+	retry?: Partial<RetryOptions>;
+	method?: Method;
+	code?: string;
+	statusCode?: number;
+	retryAfter?: number;
+	computedValue?: number;
+};
+
+const createContext = ({
+	attemptCount = 1,
+	retry,
+	method = 'GET',
+	code = 'ETIMEDOUT',
+	statusCode,
+	retryAfter,
+	computedValue = Number.POSITIVE_INFINITY,
+}: ContextOptions = {}): RetryObject => {
+	const options = new Options({method, retry: {noise: 0, ...retry}});
+	const error = new RequestError('Request failed', {code}, options);
+
+	if (statusCode !== undefined) {
+		Object.defineProperty(error, 'response', {value: {statusCode}});
+	}
+
+	return {
+		attemptCount,
+		retryOptions: options.retry as RetryOptions,
+		error,
+		retryAfter,
+		computedValue,
+	};
+};
+
+test('returns an empty array for empty input', t => {
+	t.deepEqual(retrySchedule([]), []);
+});
+
+test('returns exponential delays per context, capped by the attempt limit', t => {
+	const contexts = [1, 2, 3, 4].map(attemptCount => createContext({attemptCount, retry: {limit: 3}}));
+	t.deepEqual(retrySchedule(contexts), [1000, 2000, 4000, 0]);
+});
+
+test('caps delays at `backoffLimit`', t => {
+	const contexts = [1, 2, 3].map(attemptCount => createContext({attemptCount, retry: {limit: 3, backoffLimit: 1500}}));
+	t.deepEqual(retrySchedule(contexts), [1000, 1500, 1500]);
+});
+
+test('preserves method, error code and status code eligibility', t => {
+	t.deepEqual(retrySchedule([
+		createContext({method: 'POST'}),
+		createContext({code: 'ESOMETHING'}),
+		createContext({code: 'ERR_NON_2XX_3XX_RESPONSE', statusCode: 503}),
+		createContext({code: 'ERR_NON_2XX_3XX_RESPONSE', statusCode: 400}),
+		createContext({code: 'ERR_NON_2XX_3XX_RESPONSE', statusCode: 413, retry: {statusCodes: [413]}}),
+	]), [0, 0, 1000, 0, 0]);
+});
+
+test('honors `Retry-After` within bounds', t => {
+	t.deepEqual(retrySchedule([
+		createContext({code: 'ERR_NON_2XX_3XX_RESPONSE', statusCode: 503, retryAfter: 3000, computedValue: 5000}),
+		createContext({code: 'ERR_NON_2XX_3XX_RESPONSE', statusCode: 503, retryAfter: 6000, computedValue: 5000}),
+	]), [3000, 0]);
+});
+
+test('returns 1 for `RetryError`', t => {
+	const context = createContext({method: 'POST'});
+	const error = new RequestError('Retrying', {}, context.error.options);
+	Object.setPrototypeOf(error, RetryError.prototype);
+	error.name = 'RetryError';
+
+	t.deepEqual(retrySchedule([{...context, error}]), [1]);
+});
+
+test('throws on nonzero noise', t => {
+	t.throws(() => retrySchedule([createContext(), createContext({retry: {noise: 50}})]), {
+		instanceOf: RangeError,
+		message: /got 50 at index 1/,
+	});
+
+	t.throws(() => retrySchedule([createContext({retry: {noise: -10}})]), {instanceOf: RangeError});
+});
+
+test('is deterministic', t => {
+	const contexts = [1, 2, 3].map(attemptCount => createContext({attemptCount}));
+	t.deepEqual(retrySchedule(contexts), retrySchedule(contexts));
+});
